// Nemo kit: the clownfish, his crown and shades, and the game's sounds, shared
// by the spin-off games. The drawing and sound code below is copied from the
// main game (index.html) so the fish and the farts are exactly the same.
(() => {
  let ctx = null, t = 0;
  const ssActive = 0; // the spin-offs have no super saiyan form

  // ---------- sounds (from the main game) ----------
  let actx = null;
  function beep(freq, dur, type = 'square', vol = 0.08, slide = 0) {
    try {
      if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)();
      if (actx.state === 'suspended') actx.resume();
      const o = actx.createOscillator(), g = actx.createGain();
      o.type = type;
      o.frequency.setValueAtTime(freq, actx.currentTime);
      if (slide) o.frequency.exponentialRampToValueAtTime(slide, actx.currentTime + dur);
      g.gain.setValueAtTime(vol, actx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.0001, actx.currentTime + dur);
      o.connect(g); g.connect(actx.destination);
      o.start(); o.stop(actx.currentTime + dur);
    } catch (e) { /* audio is optional */ }
  }
  const sndSwim = () => beep(350, 0.1, 'sine', 0.1, 900);
  const sndRocket = () => beep(160, 0.18, 'sawtooth', 0.1, 60);
  function fart(dur = 0.45, freq = 140, vol = 0.35) {
    // whoopee-cushion synthesis: a periodic rubbery lip-flap that slows
    // as it deflates, with a raspberry buzz underneath, squeezed through
    // a resonant low-pass filter
    try {
      if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)();
      if (actx.state === 'suspended') actx.resume();
      const sr = actx.sampleRate;
      const n = Math.floor(sr * dur);
      const buf = actx.createBuffer(1, n, sr);
      const d = buf.getChannelData(0);
      let phase = 0;
      const wob = Math.random() * 6; // every cushion is a little different
      for (let i = 0; i < n; i++) {
        const tt = i / sr;
        const prog = i / n;
        // the flap rate starts fast and droops as the cushion empties
        const flapHz = 46 - prog * 24 + Math.sin(tt * 9 + wob) * 6;
        phase += (flapHz * 2 * Math.PI) / sr;
        const flap = Math.sin(phase) > -0.35 ? 1 : 0.07; // asymmetric rubber flap
        const rasp = Math.sin(phase * 2 + Math.sin(tt * 47) * 1.6) * 0.45; // raspberry buzz
        d[i] = ((Math.random() * 2 - 1) * 0.65 + rasp) * flap;
      }
      const src = actx.createBufferSource();
      src.buffer = buf;
      const lp = actx.createBiquadFilter();
      lp.type = 'lowpass';
      lp.Q.value = 10; // resonance gives it the honk
      lp.frequency.setValueAtTime(freq * 2.6, actx.currentTime);
      lp.frequency.exponentialRampToValueAtTime(freq * 0.55, actx.currentTime + dur);
      const g = actx.createGain();
      g.gain.setValueAtTime(vol, actx.currentTime);
      g.gain.setValueAtTime(vol, actx.currentTime + dur * 0.6);
      g.gain.exponentialRampToValueAtTime(0.001, actx.currentTime + dur);
      src.connect(lp); lp.connect(g); g.connect(actx.destination);
      src.start();
    } catch (e) { /* audio is optional */ }
  }
  // real fart recordings (chosen by the developer) embedded as data URIs
  const FART_TAP_SRC = 'data:audio/mpeg;base64,';
  const FART_PROUD_SRC = 'data:audio/mpeg;base64,';
  const fartBufs = {};
  function loadFartSamples() {
    try {
      if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)();
      for (const [key, uri] of [['tap', FART_TAP_SRC], ['proud', FART_PROUD_SRC]]) {
        if (fartBufs[key] !== undefined) continue;
        fartBufs[key] = null; // loading
        fetch(uri)
          .then(r => r.arrayBuffer())
          .then(ab => actx.decodeAudioData(ab))
          .then(b => { fartBufs[key] = b; })
          .catch(() => { delete fartBufs[key]; });
      }
    } catch (e) { /* audio is optional */ }
  }
  function playFartSample(key, rate = 1, vol = 1) {
    try {
      if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)();
      if (actx.state === 'suspended') actx.resume();
      loadFartSamples();
      const b = fartBufs[key];
      if (!b) { // not decoded yet: synth fallback so the tap isn't silent
        fart(0.32 + Math.random() * 0.2, 110 + Math.random() * 70, 0.34);
        return;
      }
      const src = actx.createBufferSource();
      src.buffer = b;
      src.playbackRate.value = rate;
      const g = actx.createGain();
      g.gain.value = vol;
      src.connect(g); g.connect(actx.destination);
      src.start();
    } catch (e) { /* audio is optional */ }
  }
  let fartTaps = 0;
  const sndFart = () => {
    // the real recording, re-pitched a little each tap; every 5th tap is the proud one
    fartTaps++;
    if (fartTaps % 5 === 0) playFartSample('proud', 0.95 + Math.random() * 0.1, 1);
    else playFartSample('tap', 0.9 + Math.random() * 0.22, 0.95);
  };
  const sndFartSong = (fancy) => {
    // a melody of the real thing, pitched up the scale; fancier as the score climbs
    const steps = [1, 1.12, 1, 1.25, 1.18, 1.33, 1.25, 1.5, 1.4, 1.6, 1.5, 1.78];
    const n = Math.min(4 + fancy * 2, steps.length);
    for (let i = 0; i < n; i++) {
      setTimeout(() => playFartSample('tap', steps[i], 0.8), i * 230);
    }
    // the proud finale on fancier renditions
    if (fancy >= 2) setTimeout(() => playFartSample('proud', 0.85, 1), n * 230);
  };
  const sndScore = () => { beep(880, 0.08, 'triangle', 0.07); setTimeout(() => beep(1320, 0.12, 'triangle', 0.07), 80); };
  const sndHit = () => beep(180, 0.3, 'sawtooth', 0.12, 50);
  const sndBlub = () => beep(300, 0.25, 'sine', 0.09, 90);
  const sndFireworks = () => {
    beep(523, 0.12, 'triangle', 0.08);
    setTimeout(() => beep(659, 0.12, 'triangle', 0.08), 100);
    setTimeout(() => beep(784, 0.12, 'triangle', 0.08), 200);
    setTimeout(() => beep(1046, 0.25, 'triangle', 0.09), 300);
  };
  const snd1Up = () => {
    // quick rising arpeggio, 1-up-mushroom style
    const seq = [659, 784, 1319, 1047, 1175, 1568];
    seq.forEach((f, i) => setTimeout(() => beep(f, 0.13, 'square', 0.06), i * 85));
  };
  const sndChest = () => {
    // treasure-chest fanfare: chromatic suspense rise, then a big held chord
    const rise = [440, 466, 494, 523, 554, 587];
    rise.forEach((f, i) => setTimeout(() => beep(f, 0.1, 'triangle', 0.06), i * 90));
    setTimeout(() => {
      beep(659, 0.8, 'square', 0.05);
      beep(831, 0.8, 'square', 0.045);
      beep(988, 0.8, 'square', 0.045);
      beep(1319, 0.8, 'triangle', 0.06);
    }, 560);
  };


  // ---------- the fish (from the main game) ----------
  function drawFishBody(k) {
    // (a second player brings their own colours in k.pal)
    const orange = k.pal ? k.pal.body : '#ff8c2e';
    const orangeDark = k.pal ? k.pal.dark : '#d96a10';
    const band = k.pal ? k.pal.band : '#fdf7ec';

    // tail fin (wags)
    const tw = Math.sin(k.tail) * 5;
    ctx.fillStyle = orange;
    ctx.beginPath();
    ctx.moveTo(-14, 0);
    ctx.quadraticCurveTo(-26, -12 + tw, -30, -8 + tw);
    ctx.quadraticCurveTo(-24, 0 + tw * 0.5, -30, 8 + tw);
    ctx.quadraticCurveTo(-26, 12 + tw, -14, 0);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = orangeDark;
    ctx.lineWidth = 2;
    ctx.stroke();

    // dorsal fin
    ctx.fillStyle = orange;
    ctx.beginPath();
    ctx.moveTo(-6, -10);
    ctx.quadraticCurveTo(-2, -20, 8, -12);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = orangeDark;
    ctx.stroke();

    // body
    ctx.fillStyle = orange;
    ctx.beginPath();
    ctx.ellipse(0, 0, 18, 12, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = orangeDark;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // white bands with dark edges (clip to body)
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(0, 0, 18, 12, 0, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = band;
    ctx.strokeStyle = '#3a2a16';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(8, -13); ctx.quadraticCurveTo(4, 0, 8, 13);
    ctx.lineTo(13, 13); ctx.quadraticCurveTo(9, 0, 13, -13);
    ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-3, -13); ctx.quadraticCurveTo(-7, 0, -3, 13);
    ctx.lineTo(3, 13); ctx.quadraticCurveTo(-1, 0, 3, -13);
    ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-13, -13); ctx.quadraticCurveTo(-16, 0, -13, 13);
    ctx.lineTo(-10, 13); ctx.quadraticCurveTo(-13, 0, -10, -13);
    ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.restore();

    // saiyan battle gi: orange suit with a blue sash while transformed
    if (ssActive > 0) {
      ctx.save();
      ctx.beginPath();
      ctx.ellipse(0, 0, 18, 12, 0, 0, Math.PI * 2);
      ctx.clip();
      ctx.fillStyle = '#e8731d';
      ctx.fillRect(-19, -13, 26, 26);
      ctx.fillStyle = '#2a4fa8';
      ctx.fillRect(3, -13, 5, 26);
      ctx.restore();
      // sash knot and dangling tails
      ctx.strokeStyle = '#2a4fa8';
      ctx.lineWidth = 2.4;
      ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(5.5, 10); ctx.lineTo(2, 16); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(5.5, 10); ctx.lineTo(8.5, 16); ctx.stroke();
      ctx.fillStyle = '#2a4fa8';
      ctx.beginPath(); ctx.arc(5.5, 10, 2.4, 0, Math.PI * 2); ctx.fill();
    }

    // pectoral fin (flaps on tap)
    const finUp = k.fin * 10;
    ctx.fillStyle = ssActive > 0 ? '#e8731d' : orangeDark;
    ctx.beginPath();
    ctx.moveTo(0, 2);
    ctx.quadraticCurveTo(-6, 10 - finUp, -12, 12 - finUp);
    ctx.quadraticCurveTo(-5, 12, 0, 7);
    ctx.closePath();
    ctx.fill();
    if (ssActive > 0) {
      // blue wristband at the fin base
      ctx.strokeStyle = '#2a4fa8';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(-1, 3);
      ctx.lineTo(-3.5, 9 - finUp * 0.5);
      ctx.stroke();
    }

    // mouth
    ctx.strokeStyle = '#3a2a16';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.arc(17, 3, 2.5, 0.2, Math.PI - 0.4);
    ctx.stroke();
  }

  function drawCrown() {
    // black & gold royal crown
    ctx.fillStyle = '#1c1c1e';
    ctx.strokeStyle = '#d4a532';
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.moveTo(5, -13);
    ctx.lineTo(6, -21);
    ctx.lineTo(9.5, -16);
    ctx.lineTo(12.5, -23);
    ctx.lineTo(15.5, -16);
    ctx.lineTo(19, -21);
    ctx.lineTo(20, -13);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#d4a532';
    ctx.fillRect(5, -14, 15, 1.8);
    ctx.beginPath(); ctx.arc(6, -21, 1.2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(12.5, -23, 1.4, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(19, -21, 1.2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#e0455c';
    ctx.beginPath();
    ctx.arc(12.5, -17, 1.6, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawShades(ph, dead) {
    if (dead) {
      ctx.strokeStyle = '#3a2a16';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(9, -6); ctx.lineTo(14, -1); ctx.moveTo(14, -6); ctx.lineTo(9, -1); ctx.stroke();
    } else {
      ctx.strokeStyle = '#141414';
      ctx.lineWidth = 1.8;
      ctx.beginPath();
      ctx.moveTo(8.5, -5);
      ctx.quadraticCurveTo(3, -7, -1, -5);
      ctx.stroke();
      // rave level: LED lenses that cycle colors with the lights
      ctx.fillStyle = ph === 4 ? `hsl(${(t * 120) % 360}, 100%, 55%)` : '#141414';
      ctx.beginPath();
      ctx.ellipse(12.5, -4, 5, 4, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#d4a532';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.strokeStyle = 'rgba(255,255,255,0.6)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(10, -6.5);
      ctx.lineTo(13.5, -2);
      ctx.stroke();
    }
  }


  // Draw Nemo at the origin of the given context, facing right, about 36
  // units long. o: { tail, fin, dead, rave, t, pal }
  function drawNemo(c, o) {
    ctx = c;
    t = o.t || 0;
    drawFishBody(o);
    drawCrown();
    drawShades(o.rave ? 4 : 1, !!o.dead);
  }

  // The five worlds of the main game, as backdrops: sky colours, the giant
  // lettering's tint, and the colours its gates are built from.
  const WORLDS = [
    { name: 'THE REEF', sky: ['#39a9d8', '#1a6ea8', '#0d4a7a'], royl: 'rgba(255,255,255,0.09)', block: ['#d8527c', '#ff7fa5', '#c2406a'], edge: 'rgba(110, 20, 50, 0.45)' },
    { name: 'SPACE', sky: ['#04040f', '#0b0b28', '#181339'], royl: 'rgba(255,217,74,0.08)', block: ['#6a7686', '#b9c4d2', '#5d6878'], edge: 'rgba(20, 25, 40, 0.55)' },
    { name: 'SAMURAI SUNSET', sky: ['#f5b16b', '#e0455c', '#5d2a4a'], royl: 'rgba(255,255,255,0.1)', block: ['#aeb9c6', '#cfd8e2', '#5d6878'], edge: 'rgba(25, 32, 45, 0.6)' },
    { name: 'NEON RAVE', sky: ['#0b001a', '#1a0033', '#2d0a4e'], royl: null, block: null, edge: 'rgba(255, 255, 255, 0.45)' },
    { name: 'THE ROYL KINGDOM', sky: ['#2a0a3a', '#7a1f4f', '#b8722a'], royl: 'rgba(255,217,74,0.12)', block: ['#9a6a08', '#ffd94a', '#8a5a06'], edge: 'rgba(120, 80, 0, 0.6)' }
  ];
  // sky gradient plus the huge ROYL lettering drifting behind the action
  function drawBackdrop(c, W, H, world, scroll, time) {
    const w = WORLDS[world % WORLDS.length];
    const g = c.createLinearGradient(0, 0, 0, H);
    g.addColorStop(0, w.sky[0]);
    g.addColorStop(0.6, w.sky[1]);
    g.addColorStop(1, w.sky[2]);
    c.fillStyle = g;
    c.fillRect(0, 0, W, H);
    const fs = H * 0.3;
    c.font = `900 ${fs}px -apple-system, "Segoe UI", Arial, sans-serif`;
    c.textAlign = 'left';
    c.textBaseline = 'middle';
    c.fillStyle = w.royl || `hsla(${(time * 50) % 360}, 90%, 60%, 0.1)`;
    const tw = c.measureText('ROYL').width + W * 0.45;
    for (let x = -(((scroll % tw) + tw) % tw); x < W; x += tw) c.fillText('ROYL', x, H * 0.38);
  }
  // the colours for something built in a given world (rave cycles with time)
  function blockColors(world, time, seed) {
    const w = WORLDS[world % WORLDS.length];
    if (w.block) return w.block;
    const hue = (time * 60 + (seed || 0) * 50) % 360;
    return [`hsl(${hue}, 95%, 35%)`, `hsl(${hue}, 100%, 65%)`, `hsl(${hue}, 95%, 30%)`];
  }

  // Effects every game shares: green fart clouds, firework sparks and the
  // "ROYL #1" lettering that floats up with them. Positions are in whatever
  // units the caller draws in; u is the size of one design unit.
  function fx() {
    let farts = [], sparks = [], texts = [];
    return {
      fart(x, y, u, dx = -1, n = 6) {
        for (let i = 0; i < n; i++) {
          farts.push({
            x: x + (Math.random() - 0.5) * 10 * u, y: y + (Math.random() - 0.5) * 12 * u,
            vx: dx * (40 + Math.random() * 60) * u, vy: (20 + Math.random() * 40) * u,
            r: (5 + Math.random() * 6) * u, life: 0.5 + Math.random() * 0.3
          });
        }
      },
      fireworks(x, y, u, label = 'ROYL #1') {
        const colors = ['#ffd94a', '#ff8c2e', '#ffffff', '#ff5c8a'];
        for (let i = 0; i < 26; i++) {
          const a = (i / 26) * Math.PI * 2 + Math.random() * 0.3, sp = (90 + Math.random() * 180) * u;
          sparks.push({ x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, life: 0.9 + Math.random() * 0.5, color: colors[i % colors.length] });
        }
        if (label) texts.push({ x, y: y - 50 * u, life: 1.6, label });
      },
      update(dt, u) {
        for (const f of farts) { f.x += f.vx * dt; f.y += f.vy * dt; f.r += 14 * u * dt; f.life -= dt; }
        farts = farts.filter(f => f.life > 0);
        for (const p of sparks) { p.x += p.vx * dt; p.y += p.vy * dt; p.vx *= 1 - dt * 1.2; p.vy = p.vy * (1 - dt * 1.2) - 60 * dt; p.life -= dt; }
        sparks = sparks.filter(p => p.life > 0);
        for (const q of texts) { q.y -= 30 * u * dt; q.life -= dt; }
        texts = texts.filter(q => q.life > 0);
      },
      drawFarts(c) {
        for (const f of farts) {
          c.globalAlpha = Math.min(1, f.life * 2) * 0.6;
          c.fillStyle = '#b9d96a';
          c.beginPath(); c.arc(f.x, f.y, f.r, 0, Math.PI * 2); c.fill();
        }
        c.globalAlpha = 1;
      },
      drawSparks(c, u) {
        for (const p of sparks) {
          c.globalAlpha = Math.min(1, p.life * 1.5);
          c.fillStyle = p.color;
          c.beginPath(); c.arc(p.x, p.y, 3 * u * Math.min(1, p.life + 0.3), 0, Math.PI * 2); c.fill();
        }
        for (const q of texts) {
          c.globalAlpha = Math.min(1, q.life);
          c.font = `bold ${30 * u}px -apple-system, "Segoe UI", Arial, sans-serif`;
          c.textAlign = 'center';
          c.textBaseline = 'middle';
          c.lineJoin = 'round';
          c.lineWidth = 4 * u;
          c.strokeStyle = '#1c1c1e';
          c.strokeText(q.label, q.x, q.y);
          c.fillStyle = '#ffd94a';
          c.fillText(q.label, q.x, q.y);
        }
        c.globalAlpha = 1;
      }
    };
  }

  // ---------- leaderboards for the spin-off games ----------
  // /boards/<game>/<device id> = { name, score, ts }: one entry per device per
  // game, and the rules only let a score go up, so a board can never hold
  // more rows than there are players. Name and device id are the main game's.
  const DB = 'https://royal-nemo-default-rtdb.firebaseio.com';
  const boardUrl = (g, p) => DB + '/boards/' + g + (p ? '/' + p : '') + '.json';
  const GAMES = ['stack', 'swing'];
  function deviceId() {
    let id = localStorage.getItem('royalNemoPid');
    if (!id) {
      id = Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
      localStorage.setItem('royalNemoPid', id);
    }
    return id;
  }
  const cleanName = n => Array.from(String(n || '').trim()).slice(0, 12).join('').trim();
  const playerName = () => cleanName(localStorage.getItem('royalNemoName'));
  function board(game, unit) {
    const PID = deviceId();
    let rows = null, off = false, shown = true;
    const css = 'font:bold 14px -apple-system,"Segoe UI",Arial,sans-serif;color:#fff;';
    const el = (tag, style, txt) => { const e = document.createElement(tag); e.style.cssText = style; if (txt) e.textContent = txt; return e; };
    const btn = el('button', css + 'position:fixed;top:max(10px,env(safe-area-inset-top));right:10px;z-index:5;background:rgba(13,50,90,0.7);border:2px solid #ffd94a;border-radius:18px;padding:7px 14px;cursor:pointer;', '🏆 Top 100');
    btn.type = 'button';
    const overlay = el('div', 'position:fixed;inset:0;z-index:10;display:none;align-items:center;justify-content:center;background:rgba(0,20,40,0.7);');
    const card = el('div', css + 'background:#0d4a7a;border:3px solid #ffd94a;border-radius:16px;padding:18px;width:min(88vw,340px);max-height:82vh;display:flex;flex-direction:column;text-align:center;');
    const title = el('div', 'font-size:20px;color:#ffd94a;margin-bottom:4px;', '🏆 TOP 100');
    const sub = el('div', 'font-size:12px;font-weight:normal;color:#cdeef5;margin-bottom:10px;');
    const list = el('div', 'overflow-y:auto;text-align:left;font-size:15px;flex:1;min-height:60px;');
    const who = el('button', css + 'font-size:13px;background:transparent;border:1px solid #39a9d8;border-radius:10px;padding:7px 12px;margin-top:10px;color:#cdeef5;cursor:pointer;');
    const close = el('button', 'font:bold 16px -apple-system,"Segoe UI",Arial,sans-serif;color:#123a5c;background:#ffd94a;border:none;border-radius:10px;padding:9px 24px;margin-top:10px;cursor:pointer;', 'Close');
    who.type = close.type = 'button';
    card.append(title, sub, list, who, close);
    overlay.append(card);
    document.body.append(btn, overlay);

    function render() {
      who.textContent = '👤 Playing as ' + (playerName() || 'Nemo') + ' · change name';
      list.textContent = '';
      if (off) { sub.textContent = 'The leaderboard is not switched on yet.'; return; }
      if (!rows) { sub.textContent = 'loading…'; return; }
      sub.textContent = rows.length ? rows.length + (rows.length === 1 ? ' player' : ' players') + ' so far' : 'No scores yet. Be the first!';
      rows.slice(0, 100).forEach((r, i) => {
        const mine = r.pid === PID;
        const row = el('div', 'display:flex;gap:8px;padding:5px 4px;border-bottom:1px solid rgba(255,255,255,0.12);' + (mine ? 'color:#ffd94a;' : ''));
        row.append(el('span', 'width:30px;text-align:right;opacity:0.8;', (i + 1) + '.'),
                   el('span', 'flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;', r.name),
                   el('span', '', r.score + ' ' + unit));
        list.append(row);
      });
    }
    async function refresh() {
      try {
        const res = await fetch(boardUrl(game));
        if (!res.ok) { off = res.status === 401 || res.status === 403; render(); return; }
        off = false;
        const data = await res.json() || {};
        rows = Object.entries(data)
          .filter(([, e]) => e && typeof e.score === 'number' && e.name)
          .map(([pid, e]) => ({ pid, name: String(e.name).slice(0, 24), score: e.score, ts: +e.ts || 0 }))
          .sort((a, b) => b.score - a.score || a.ts - b.ts);
        render();
      } catch (e) { /* offline: keep what we had */ }
    }
    function askName() {
      const n = cleanName(window.prompt('Your name for the leaderboard (up to 12 letters):', playerName() || ''));
      if (!n) return false;
      localStorage.setItem('royalNemoName', n);
      // carry the new name onto this device's row in every spin-off board
      for (const g of GAMES) {
        fetch(boardUrl(g, PID)).then(r => (r.ok ? r.json() : null)).then(e => {
          if (!e || typeof e.score !== 'number') return;
          return fetch(boardUrl(g, PID), { method: 'PUT', body: JSON.stringify({ name: n, score: e.score, ts: +e.ts || Date.now() }) });
        }).then(() => { if (g === game) refresh(); }).catch(() => {});
      }
      render();
      return true;
    }
    function submit(score) {
      if (!(score > 0)) return;
      if (!playerName()) askName(); // first score on this device: ask once
      const body = { name: playerName() || 'Nemo', score: Math.floor(score), ts: Date.now() };
      fetch(boardUrl(game, PID), { method: 'PUT', body: JSON.stringify(body) }).catch(() => {}).then(refresh);
    }
    btn.addEventListener('click', () => { overlay.style.display = 'flex'; render(); refresh(); });
    close.addEventListener('click', () => { overlay.style.display = 'none'; });
    who.addEventListener('click', askName);
    refresh();
    return {
      refresh, submit,
      isOpen: () => overlay.style.display === 'flex',
      show(v) { if (v !== shown) { shown = v; btn.style.display = v ? 'block' : 'none'; } },
      // this device's saved row, so a game can re-send a best the board never got
      mine: () => (rows ? rows.find(r => r.pid === PID) || null : undefined),
      // one line for the title and game-over screens
      line() {
        if (off || !rows || !rows.length) return '';
        const i = rows.findIndex(r => r.pid === PID), top = rows[0];
        const lead = top.pid === PID ? "You're #1!" : `#1 ${top.name}: ${top.score} ${unit}`;
        return i > 0 ? `🌍 You're #${i + 1} of ${rows.length}  ·  ${lead}` : '🌍 ' + lead;
      }
    };
  }

  window.NemoKit = {
    beep, fart, loadFartSamples, playFartSample, sndFart, sndFartSong,
    sndScore, sndHit, sndBlub, sndFireworks, snd1Up, sndChest,
    drawNemo, drawBackdrop, blockColors, WORLDS, fx, board
  };
})();
